        jdbc.update("DELETE FROM setting WHERE sheet_id = ? AND setting_key = ?", setting.sheetId(), setting.key());
        jdbc.update("INSERT INTO setting (sheet_id, setting_key, setting_value) VALUES (?, ?, ?)",
