import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Closes an open period, fixing its due-total as it is now: the figures of the claims that count (a held person's OPEN claims do not) whose date falls
 *  in it, added up (skipping n/a). Closing a period already closed is refused. */
public class ClosePeriod {
    public void close(@Val Period period, @Val PeriodCloseRequest request, PeriodRepository periods,
            ClaimRepository claims, PersonRepository people, RateRepository rates, Out<PeriodClose> closed)
            throws InvalidPeriodException {
        if (period.closed()) {
            throw new InvalidPeriodException("The period " + period.name() + " is already closed");
        }
        Map<Long, Person> byId = people.list(period.sheetId()).stream()
                .collect(Collectors.toMap(Person::id, (p) -> p));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim c : claims.list(period.sheetId())) {
            Person person = byId.get(c.personId());
            if (!ClaimDue.countsLive(c, person != null && person.held()) || c.date().isBefore(period.from()) || c.date().isAfter(period.to())) {
                continue;
            }
            BigDecimal figure = person == null ? c.due() : ClaimDue.figure(c, person.grade(), rates);
            if (figure != null) {
                total = total.add(figure);
            }
        }
        if (!periods.close(period, total)) {
            throw new InvalidPeriodException("The period " + period.name() + " is already closed");
        }
        closed.set(new PeriodClose(request.by(), total));
    }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPage } from '../../slots/defs/sheetPage';
import { settingsKey, useSettings, type Setting } from './settings';

/** The sheet's settings: the clerk limit (the most a clerk may settle a claim's due for; blank for no limit). */
function Settings({ sheetId, user }: { sheetId: string; user: string }) {
  const settings = useSettings(sheetId);
  const queryClient = useQueryClient();
  const [limit, setLimit] = useState('');

  const submit = useSubmitOnce();
  const save = useMutation({
    mutationFn: (value: string) =>
      putJson<Setting>(`/api/sheets/${encodeURIComponent(sheetId)}/settings/clerk-limit`, { value, by: user }),
    onSuccess: () => {
      setLimit('');
      void queryClient.invalidateQueries({ queryKey: settingsKey(sheetId) });
    },
    onSettled: submit.end,
  });
  const current = settings.data?.find((s) => s.key === 'clerk-limit')?.value ?? '';

  return (
    <section data-testid="settings">
      <h3>Settings</h3>
      <form
        data-testid="settings-form"
        onSubmit={(e) => {
          e.preventDefault();
          if (!submit.begin()) return;
          save.reset();
          save.mutate(limit);
        }}
      >
        <label>
          Clerk limit{' '}
          <input
            data-testid="setting-clerk-limit"
            inputMode="decimal"
            value={limit}
            onChange={(e) => {
              setLimit(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="settings-save" disabled={save.isPending}>
          Save settings
        </button>
        {save.isError && (
          <span data-testid="settings-error">The clerk limit must be an amount with up to two decimals, or blank.</span>
        )}
      </form>
      {settings.isError && <p data-testid="settings-load-error">Could not load settings.</p>}
      <p>
        Clerk limit in force <span data-testid="setting-clerk-limit-current">{current}</span>
      </p>
    </section>
  );
}

