# PUT /api/sheets/{sheetId}/rates/{grade} — set a grade's rate, a percent with two decimals, from
# an optional from-date (none: from the beginning of time), replacing any it had for that
# from-date. A grade other than A, B or C, a rate that is not a number 0.00 or more with up to two
# decimals, or a from-date that is not yyyy-MM-dd, is a 400 and writes nothing. Responds with the
# rate as stored.
validate:
  class: net.officefloor.hq.app.rate.ValidateRate
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.rate.SaveRate
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.rate.RecordRateSet
  govern: [ transaction ]
  next: respond
respond:
